import Foundation

/// Genuine `RNS/vendor/umsgpack.py` output for every integer-width boundary, for float32 vs
/// float64, and for a map32. Generated by `generate_msgpack_signed_fixtures.py`.
struct MsgPackSignedFixtures: Decodable {
    struct Integer: Decodable {
        /// Decimal string — `Int64.min` and `UInt64.max` do not both fit one JSON number type.
        let value: String
        let packed: String
    }
    struct Float32: Decodable {
        let value: String
        let packedSingle: String
        let packedDouble: String

        enum CodingKeys: String, CodingKey {
            case value
            case packedSingle = "packed_single"
            case packedDouble = "packed_double"
        }
    }

    let integers: [Integer]
    let floats: [Float32]
    let map32EntryCount: Int
    let map32PackedLength: Int
    let map32PackedSha256: String
    let map32PackedPrefix: String
    let smallMap32Packed: String

    enum CodingKeys: String, CodingKey {
        case integers, floats
        case map32EntryCount = "map32_entry_count"
        case map32PackedLength = "map32_packed_length"
        case map32PackedSha256 = "map32_packed_sha256"
        case map32PackedPrefix = "map32_packed_prefix"
        case smallMap32Packed = "small_map32_packed"
    }

    static func load() throws -> MsgPackSignedFixtures {
        let url = Bundle.module.url(forResource: "msgpack_signed_fixtures", withExtension: "json")!
        return try JSONDecoder().decode(MsgPackSignedFixtures.self, from: Data(contentsOf: url))
    }
}

/// A genuine lxmf 1.1.0 message whose `fields` carry negative integers.
/// Generated by `generate_lxmf_signed_fixtures.py`.
struct LXMFSignedFixtures: Decodable {
    let sourcePrivateKey: String
    let destinationHash: String
    let timestamp: Double
    let title: String
    let content: String
    /// Decimal strings, one per signed encoding width plus two scaled coordinates.
    let telemetry: [String]
    let renderer: Int
    let hash: String
    let signature: String
    let packed: String

    enum CodingKeys: String, CodingKey {
        case sourcePrivateKey = "source_private_key"
        case destinationHash = "destination_hash"
        case timestamp, title, content, telemetry, renderer, hash, signature, packed
    }

    static func load() throws -> LXMFSignedFixtures {
        let url = Bundle.module.url(forResource: "lxmf_signed_fixtures", withExtension: "json")!
        return try JSONDecoder().decode(LXMFSignedFixtures.self, from: Data(contentsOf: url))
    }
}
